<main class="py-5"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 text-primary mb-1">Mes commandes</h1><p class="text-muted mb-0">Suivez vos prestations et leurs statuts.</p></div><a class="btn btn-primary" href="/orders/new">Nouvelle commande</a></div>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>N°</th><th>Date de prestation</th><th>Personnes</th><th>Statut</th><th>Total</th></tr></thead><tbody>
